const DEF={ocupada:false,ac:true,luz:true,modo:'ON',potencia:1450,energia:12.34,online:true,ts:Date.now(),oled:''};
const s=global.get('campus')||DEF;
if(s.luz===undefined) s.luz=true;
// Carga controlada da Sala 101: ON = energizada | OFF = cortada | AUTO = energizada somente com a sala ocupada.
const cargaLigada=x=>x.modo==='ON'||(x.modo==='AUTO'&&x.ocupada===true);
const now=Date.now();
if(!s.online){ s.ts=now; global.set('campus',s); msg.statusCode=503; msg.payload={erro:'dispositivo offline'}; return msg; }
// Consumo acumulado = soma de (potência x tempo). O intervalo é limitado a 60 s para que um período sem leituras
// (aba fechada, Node-RED parado) não vire um salto de energia de uma vez só.
const dt=Math.min(Math.max(now-(s.ts||now),0),60000)/3600000;
const lig=cargaLigada(s);
// Potência: 200 W fixos (sensores e display) + equipamentos SOMENTE quando a carga está energizada.
const base=200+(lig?(s.ac?1100:0)+(s.luz?100:0)+150:0);
s.potencia=Math.round(base+(Math.random()-0.5)*80);
s.energia=+(s.energia+s.potencia/1000*dt).toFixed(4);
s.ts=now; global.set('campus',s);
msg.statusCode=200;
msg.payload={sala:101,timestamp:new Date(now).toISOString(),ocupada:s.ocupada,
 temperatura:+(s.ac&&lig?23+Math.random():27+Math.random()).toFixed(1),umidade:Math.round(55+Math.random()*4),
 potencia_w:s.potencia,energia_kwh:s.energia,ac:{ligado:s.ac},iluminacao:{ligada:s.luz},carga:{modo:s.modo,ligada:lig}};
return msg;

