const offline=()=>{msg.statusCode=503;msg.payload={erro:'dispositivo offline'};return msg;};
function lerCorpo(){ // aceita objeto (JSON), texto ou Buffer (text/plain, sem preflight)
  let b=msg.payload; if(b===undefined||b===null||b==='') b=msg.req&&msg.req.body;
  if(Buffer.isBuffer(b)) b=b.toString('utf8');
  if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ return null; } }
  return (b&&typeof b==='object')?b:null;
}
const b=lerCorpo(); const cmd=String((b&&b.comando)||'').toUpperCase();
if(!['ON','OFF','AUTO'].includes(cmd)){msg.statusCode=400;msg.payload={erro:'comando inválido (use ON, OFF ou AUTO)'};return msg;}
if(!s.online) return offline();
s.modo=cmd; global.set('campus',s);
