// ÚNICO ponto de CORS: toda resposta (200, 400, 404, 503, 500) passa por aqui antes do http response.
const lista=String(env.get('CORS_ORIGINS')||'http://127.0.0.1:5500,http://localhost:5500').split(',').map(x=>x.trim()).filter(Boolean);
const origem=(msg.req&&msg.req.headers&&msg.req.headers.origin)||'';
const h=Object.assign({},msg.headers);
h['Access-Control-Allow-Methods']='GET,POST,OPTIONS';
h['Access-Control-Allow-Headers']='Content-Type, Accept';
h['Access-Control-Max-Age']='600';
h['Vary']='Origin';
if(lista.includes('*')) h['Access-Control-Allow-Origin']='*';
else if(origem && lista.includes(origem)) h['Access-Control-Allow-Origin']=origem;
msg.headers=h;
